Pra quem gosta de brincar um pouco mais com o código, eu fiz dessa outra forma:

func megaSenaGeneratorValores(_ total: Int,
                         _ interval: ClosedRange<Int>) -> String {

  var resultado: Set<Int> = [],
      numbers = total,
      mentirinha: String = ""

  while(numbers > 0){

    let generated = Int.random(in: interval),
        resposta = resultado.insert(generated)

    if (resposta.inserted) {
        numbers -= 1
        mentirinha += ("\(resultado)\n")
    }
  }

  return mentirinha
}

func megaSenaGeneratorValorFinal(_ total: Int,
                         _ interval: ClosedRange<Int>) -> Set<Int> {

  var resultado: Set<Int> = [],
      numbers = total

  while(numbers > 0){

    let generated = Int.random(in: interval),
        resposta = resultado.insert(generated)

    if (resposta.inserted) {
      numbers -= 1
    }
  }
  return resultado
}

let respostaUm = megaSenaGeneratorValores(10, -100...500)
let respostaDois = megaSenaGeneratorValorFinal(10, -100...500)

print("\(respostaUm)\n\(respostaDois)")

