import java.util.Scanner;

public class Calculate {
    public static void main(String[] args) {
        calculate();
    }

    static void calculate() {
        int choice, x, y;

        Scanner read = new Scanner(System.in);

        System.out.println("Calculadora");

        System.out.println("1 - Soma\n2 - Subtração\n3 - Divisão\n4 - Multiplicação");

        System.out.println("Escolha a operação:");
        choice = read.nextInt();

        if (choice > 4 || choice <= 0) {
            System.out.println("Opção invãlida!");
            return;
        }

        System.out.println("Digite o primeiro valor:");
        x = read.nextInt();

        System.out.println("Digite o segundo valor:");
        y = read.nextInt();

        switch (choice) {
            case 1 -> sum(x, y);
            case 2 -> subtraction(x, y);
            case 3 -> division(x, y);
            case 4 -> multiplication(x, y);
        }
    }

    static void sum(int x, int y) {
        var sum = x + y;
        System.out.println("Resultado da soma: " + sum);
    }

    static void subtraction(int x, int y) {
        var subtraction = x - y;
        System.out.println("Resultado da subtração: " + subtraction);
    }

    static void division(int x, int y) {
        if (x == 0 || y == 0) {
            System.out.println("Não é possivel divvidir por 0");
            return;
        }

        var division = x / y;
        System.out.println("Resultado da divisão: " + division);
    }

    static void multiplication(int x, int y) {
        var multiplication = x * y;
        System.out.println("Resultado da multiplicação: " + multiplication);
    }
}

