import java.util.Scanner;

public class Fibonacci {


    public static int setNumber(){
        System.out.println("Informe o numero para saber sua sequencia Fibonacci:");
        Scanner scanner = new Scanner(System.in);
        int num = scanner.nextInt();
        scanner.close();
        return num;
    }

    public static int recursao_Fibonacci(int n){
        if (n < 2) {
            return n;
        }
        else {
            return recursao_Fibonacci(n-1) + recursao_Fibonacci(n-2);
        }

    }

    public static void main(String[] args) {
        int n = setNumber();

        System.out.println("O " + n + " número da sequência de Fibonacci é:" + recursao_Fibonacci(n));

    }
}

