import java.util.Scanner;

public class Mathematics {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Digite o primeiro valor: ");
        int x = scanner.nextInt();

        System.out.println("Digite o segundo valor: ");
        int y = scanner.nextInt();

        System.out.println("Digite a operação que deseja (somar, subtrair, dividir, multiplicar): ");
        String operation = scanner.next();

        if (operation.equals("somar")) {
            sum(x, y);
        } else if (operation.equals("subtrair")) {
            minus(x, y);
        } else if (operation.equals("dividir")) {
            divided(x, y);
        } else if (operation.equals("multiplicar")) {
            multiply(x, y);
        } else {
            System.out.println("Operação inválida");
        }
    }

    static void sum(int x, int y) {
        System.out.println("A soma dos números inseridos é igual a: " + (x + y));
    }

    static void minus(int x, int y) {
        System.out.println("A subtração dos números inseridos é igual a: " + (x - y));
    }

    static void divided(int x, int y) {
        if (y == 0) {
            System.out.println("Não é possível dividir por zero.");
        } else {
            System.out.println("A divisão dos números inseridos é igual a: " + ((double) x / y));
        }
    }

    static void multiply(int x, int y ) {
        System.out.println("A multiplicação dos números inseridos é igual a: " + (x * y));
    }
}

